from pathlib import Path
from lesson_authoring import entry as E
D=[['拉丁语 digitus','手指、脚趾；与计数有关的用法'],['英语 digit','一个数码；也可指手指或脚趾']]
T=[['拉丁语 digitus → digitalis','手指、脚趾 → 与其有关的'],['英语 digital','与数字有关；后来用于数字技术']]
Z=D+[['digit + -ize → digitize','现代常指把资料转成数字形式']]
W=[
E('digit','/ˈdɪdʒɪt/','数码、数字位；手指或脚趾','伸出手指一下一下数：身体上的一根指头，联系到书写数字的一位。','借自拉丁 digitus“手指、脚趾”；数码义与用手指计数有关。不要把 di- 拆成“二”。',D,'电话号码里的每一位都可以叫 a digit。十进制里 0 到 9 是十个数码，数字 28 则由两个 digits 组成。身体义仍存在于较专业的描述里。英语的数码义记录比手指义早，不能把拉丁语的意义联系误写成英语先有手指义、后来才有数字义。','the last four digits；a digit is missing；a decimal digit。','number 是整个数，digit 是组成数字写法的一位。28 是一个 number，写出来有两个 digits。',('Please enter the last four digits of your phone number.','请输入你电话号码的最后四位。'),('The code is wrong because one digit is missing.','密码不对，因为少了一位数字。'),sources=['https://www.etymonline.com/word/digit','https://en.wiktionary.org/wiki/digit']),
E('digital','/ˈdɪdʒɪtəl/','数字的；数码的；与手指或脚趾有关的','把信息表示成可以记录、处理的数字，而不只是说“用了电”。','借自拉丁 digitalis，来自 digitus；现代可看出 digit + -al 的关系，但不是电脑时代才新造的词。',T,'digital camera 把图像保存为数字数据；digital clock 常指用数字显示时间的钟。新闻中的 digital services 则泛指通过数字技术提供的服务。词义范围会随语境变化，但“数字表示、处理”比“很先进”更能抓住核心。','digital technology；a digital camera；digital skills；a digital clock。','digital 不等于 electronic：电子设备也可能处理模拟信号。身体语境中的 digital 则可能仍是“手指或脚趾的”。',('I keep digital copies of important documents.','我保存着重要文件的电子版。'),('The course helps older adults develop digital skills.','这门课程帮助老年人掌握数字技术的使用技能。'),sources=['https://www.etymonline.com/word/digital','https://en.wiktionary.org/wiki/digital']),
E('digitally','/ˈdɪdʒɪtəli/','以数字方式；通过数字技术','说明事情“怎样做”：资料以数字形式处理、保存或传送。','digital + -ly，把形容词变成说明方式的副词。',T+[['digital + -ly → digitally','以数字方式']],'digitally restored 是利用数字技术修复，digitally stored 是以数字形式保存。它描述做事的方式，不保证内容真实；a digitally altered image 就可能是经过技术修改的图像。','store digitally；digitally restored；digitally altered；digitally sign。','digital 修饰事物，如 digital files；digitally 常修饰动作，如 store digitally。数字处理也不必一直联网。',('The old film has been digitally restored.','这部老电影已经用数字技术修复。'),('All receipts are stored digitally in one folder.','所有收据都以电子形式保存在一个文件夹里。'),sources=['https://en.wiktionary.org/wiki/digitally']),
E('digitize','/ˈdɪdʒɪtaɪz/','把……转成数字形式；将资料数字化','把纸、磁带等材料里的内容，变成计算机能保存和处理的数据。','digit + -ize；早期还出现过与手指操作有关的用法，今天通常学习数字技术义。',Z,'扫描旧照片、把磁带转成音频文件，都可以说 digitize。重点是改变内容的表示和保存形式，不只是把原物放到另一个房间。扫描得到图片不等于已经识别出可搜索文字，后者还需要相应处理。','digitize photographs；digitize an archive；digitize recordings。','digitize 是转换动作，digital 是属性。把纸质目录搬到办公室里并没有 digitize 它。',('Volunteers are helping the library digitize old newspapers.','志愿者正在帮助图书馆把旧报纸数字化。'),('We digitized the tapes so that the recordings would be easier to share.','我们把磁带转成数字文件，让录音更方便分享。'),sources=['https://www.etymonline.com/word/digitize','https://en.wiktionary.org/wiki/digitize']),
E('digitise','/ˈdɪdʒɪtaɪz/','把……数字化〔英式常见拼写〕','和 digitize 做同一件事：让原来的材料变成数字数据。','digit + -ise；对应 digitize 的拼写变体，s 在这里同样读 /z/。',Z+[['拼写变体 digitise','英式英语中常见，意义不变']],'digitise 常出现在英国机构的资料整理项目中。不要因为 s、z 不同就想成两种技术。英国英语也使用 -ize 拼写，写作时跟随所采用的拼写规范即可。','digitise records；digitise a collection；a project to digitise。','digitise 和 digitize 是拼写差异；digit 是名词，不能直接替换这个动词。',('The museum plans to digitise its collection of letters.','博物馆计划将收藏的书信数字化。'),('Can you digitise these photographs without damaging them?','你能在不损坏这些照片的情况下把它们数字化吗？'),sources=['https://en.wiktionary.org/wiki/digitise','https://www.etymonline.com/word/digitize']),
E('digitization','英 /ˌdɪdʒɪtaɪˈzeɪʃən/；美 /ˌdɪdʒɪtəˈzeɪʃən/','数字化；转换为数字资料的过程','把“正在把东西转成数字文件”这个动作，作为一个项目或过程来谈。','digitize + -ation；构词时去掉词尾 e，组成 digitization。',Z+[['digitize + -ation → digitization','数字化的过程']],'the digitization of records 指把记录转换成数字形式这项工作。它往往涉及整理、扫描、校对和保存，但这个词本身不承诺所有步骤都已做完。讨论项目时，问清楚数字化到了哪一步比只听一个大词有用。','the digitization of archives；a digitization project。','digitize 是动词，digitization 是名词。它和 digitalization 在实际使用中有重叠，不能只凭拼写强行划出绝对界限。',('Digitization has made the archive easier to search.','数字化让这批档案更容易检索。'),('The digitization project will begin with the oldest maps.','数字化项目将从最古老的地图开始。'),sources=['https://en.wiktionary.org/wiki/digitization','https://www.oxfordlearnersdictionaries.com/definition/english/digitization']),
E('digitisation','英 /ˌdɪdʒɪtaɪˈzeɪʃən/','数字化〔英式常见拼写〕','仍然是把资料转成数字形式这一过程，换了拼写习惯。','digitise + -ation；与 digitization 对应。',Z+[['digitise + -ation → digitisation','采用 -ise 拼写体系的过程名词']],'digitisation 不表示更高级的数字化。阅读英国博物馆、图书馆的说明时，可以直接与 digitization 对应。一个文档里最好维持同一套拼写，免得读者误以为你在区分概念。','digitisation of documents；a digitisation programme。','digitisation 与 digitization 主要是拼写差异；不要把它们分别定义为扫描和自动化。',('The archive received funding for the digitisation of its records.','档案馆获得了用于档案数字化的资金。'),('Careful digitisation can make fragile documents available to more readers.','细致的数字化工作能让更多读者接触到易损的文献。'),sources=['https://en.wiktionary.org/wiki/digitisation','https://www.oxfordlearnersdictionaries.com/definition/english/digitization']),
E('digitalize','美 /ˈdɪdʒɪtəlaɪz/','将……数字化；使采用数字技术','可以指把资料变成数字形式，也常用于把工作流程转向数字技术。','数字技术义来自 digital + -ize；另有来自 digitalis 的医学同形词，本页不展开。',T+[['digital + -ize → digitalize','使数字化、采用数字方式']],'digitalize records 可以和 digitize records 指向相近工作；digitalize workflows 则更容易让人想到工作流程整体改用数字技术。两词有重叠，不能规定 digitize 永远只管材料、digitalize 永远只管组织。先看作者实际描述了什么变化。','digitalize records；digitalize services；digitalize workflows。','处理具体图片和文件时 digitize 很常用；digitalize 常用于较宽的流程或服务表述，但不是一道严格的术语分界。',('The agency wants to digitalize its application process.','这家机构希望让申请流程采用数字方式。'),('The team digitalized the paper records before moving offices.','团队在搬办公室前把纸质记录数字化了。'),sources=['https://www.merriam-webster.com/dictionary/digitalize','https://en.wiktionary.org/wiki/digitalize']),
E('digitalization','英 /ˌdɪdʒɪtəlaɪˈzeɪʃən/；美 /ˌdɪdʒɪtələˈzeɪʃən/','数字化；数字技术的采用过程','既可能是资料形式的转换，也可能是在说整个服务或流程改变了做法。','digitalize + -ation，也可分析为 digital + -ization；保留 digital 的完整词干。',T+[['digitalize → digitalization','数字化这一过程或变化']],'digitalization of public services 可以包括网上申请、电子记录和系统间的信息交换。有些商业文章把它与 digitization 区分，前者谈流程、后者谈资料，但普通词典和实际用例也有交叉。理解时先问“什么东西发生了什么改变”。','digitalization of services；digitalization of records；digitalization efforts。','digitalization 不自动等于业务已经变好，也不自动等于全面自动化；这些效果需要上下文另行说明。',('Digitalization allowed residents to submit forms from home.','数字化使居民可以在家提交表格。'),('The report examines the costs of digitalization for small businesses.','报告考察了数字化对小企业带来的成本。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/digitalization','https://www.merriam-webster.com/dictionary/digitalization'])]
ROOT=dict(id='C0329',meaning='手指、脚趾；数码；数字技术',core='DIGIT = FINGER → NUMERICAL DIGIT',image='掰着手指数一、二、三，再把数量写成数字；现代计算机继续使用数字表示信息。',intro='拉丁 digitus 是手指或脚趾，手指与计数的关系连接了身体义和数码义。英语 digit 的数码义记录较早；这里的箭头展示意义联系，不冒充英语各词义的出现时间表。digital 经拉丁形容词 digitalis 传来，现代数字技术义是后来的发展。',forms='digit 是一位数码；digital 描述数字属性；digitally 说明方式；digitize／digitise 是转换动作；digitization／digitisation 是相应过程名词。digitalize、digitalization 与较短形式在实际用法中重叠。',branches=[['从计数理解基础词','digit, digital, digitally'],['把资料转成数字形式','digitize, digitise, digitization, digitisation'],['资料、服务和流程数字化','digitalize, digitalization']],contrasts='digit 不等于整个 number；digital 不等于一切 electronic。技术文章可能特意区分 digitization 与 digitalization，但这种区分不是所有作者都严格采用的规则。',practice='We digitized the records and stored the digital files in a searchable archive.\n\n我们把记录数字化，并将数字文件存入可检索的档案库。',words=[w['word'] for w in W],exclude={w:'生物形态或低频专门构词，暂略' for w in ['digitigrade','digitate','bidigitate','digitiform','multidigitate','multidigit']})
if __name__=='__main__':
 for name,data in [('roots_digit',[ROOT]),('words_digit',W)]:Path('.cache/batch200/drafts/root/'+name+'.json').write_text(json.dumps(data,ensure_ascii=False,indent=2))
 rows=[]
 for x in W:
  if x['word'] in ['digitise','digitisation','digitalize']:
   rows.append(dict(word=x['word'],pos='noun' if x['word']=='digitisation' else 'verb',ipa=x['ipa'],gloss={'digitise':'British spelling of digitize.','digitisation':'British spelling of digitization.','digitalize':'To convert to digital form or introduce digital technology.'}[x['word']],meaning_zh=x['meaning'],etymology_text={'digitise':'From digit + -ise; variant of digitize.','digitisation':'From digitise + -ation.','digitalize':'In the computing sense, from digital + -ize.'}[x['word']],sources=x['sources']))
 Path('.cache/batch200/root_digit_supplement_request.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2))
 print(len(W),sum(len(w['examples']) for w in W))
